/*
 * Live preview for the settings page.
 *
 * Clay serialises this function with `tosource` and injects it into the config
 * webview, so it MUST be self-contained: no references to anything outside its
 * own body. That is why the livery table is repeated here rather than shared.
 * It mirrors the table at the top of src/c/main.c — change one, change both.
 */

module.exports = function cadencePreview() {
  var clayConfig = this;

  /* The watch's own label face, embedded so the preview shows real sizes rather
     than a monospace stand-in. Same TTF as resources/fonts/. */
  var SILK_SRC = 'data:font/ttf;base64,';

  var L = [
    { n: 'ZWIFT', bg: '#000000', ink: '#FFFFFF', dim: '#AAAAAA', day: '#FF5500',
      night: '#005555', accent: '#55FFFF', panel: '#FFFFFF', pink: '#000000',
      line: '#555555', chk: '#FFFFFF',
      sw: { t: 'diag', b: [[8, '#FF5500'], [7, '#000000'], [3, '#55FFFF'], [7, '#000000']] } },
    { n: 'SURLY', bg: '#000000', ink: '#FFFFFF', dim: '#AAAAAA', day: '#AAFF00',
      night: '#005500', accent: '#FF5500', panel: '#AAFF00', pink: '#000000',
      line: '#005500', chk: '#AAFF00',
      sw: { t: 'check', size: 6, c: ['#AAFF00', '#000000', '#005500', '#000000'] } },
    { n: 'EF EDUCATION', bg: '#FF55AA', ink: '#000000', dim: '#AA0055', day: '#AAFFFF',
      night: '#AA0055', accent: '#FF0000', panel: '#000000', pink: '#AAFFFF',
      line: '#000000', chk: '#000000',
      sw: { t: 'bands', b: [[10, '#FF55AA'], [8, '#AAFFFF'], [3, '#000000'], [8, '#AAFFFF']] } },
    { n: 'VISMA', bg: '#000000', ink: '#FFFFFF', dim: '#AAAAAA', day: '#FFFF00',
      night: '#555500', accent: '#FF0000', panel: '#FFFF00', pink: '#000000',
      line: '#555500', chk: '#FFFF00',
      sw: { t: 'bands', b: [[11, '#FFFF00'], [8, '#000000'], [3, '#FFFF00'], [8, '#000000']] } },
    { n: 'INEOS 26', bg: '#FFFFFF', ink: '#000000', dim: '#555555', day: '#FF5500',
      night: '#555555', accent: '#0055AA', panel: '#FFFFFF', pink: '#000000',
      line: '#AA5500', chk: '#000000',
      sw: { t: 'dither', c: ['#FF5500', '#FFFFFF'] } },
    { n: 'LA VIE CLAIRE', bg: '#FFFFFF', ink: '#000000', dim: '#555555', day: '#FFFF00',
      night: '#0055AA', accent: '#FF0000', panel: '#FFFFFF', pink: '#000000',
      line: '#000000', chk: '#000000',
      multi: ['#FF0000', '#FFFF00', '#0055AA', '#000000'],
      sw: { t: 'blocks', gut: '#000000', c: ['#FFFFFF', '#FF0000', '#FFFF00', '#0055AA'],
            r: [[0, 0, 60, 30, 0], [64, 0, 100, 30, 1], [0, 34, 100, 60, 2],
                [0, 64, 44, 100, 3], [48, 64, 100, 100, 0]] } },
    { n: 'MAPEI', bg: '#FFFFFF', ink: '#000000', dim: '#555555', day: '#00AA00',
      night: '#0055AA', accent: '#FF0000', panel: '#FFFFFF', pink: '#000000',
      line: '#000000', chk: '#000000',
      multi: ['#FF0000', '#0055AA', '#00AA00', '#FFFF00'],
      sw: { t: 'cubes', size: 11, gut: '#FFFFFF',
            c: ['#FF0000', '#0055AA', '#00AA00', '#FFFF00', '#FFFFFF'] } }
  ];


  var BAYER = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]];
  var SUNRISE = 386, SUNSET = 1202;               /* sample sun times */
  var DOW = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  var MON = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN',
             'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  function lum(h) {
    return (299 * parseInt(h.substr(1, 2), 16) +
            587 * parseInt(h.substr(3, 2), 16) +
            114 * parseInt(h.substr(5, 2), 16)) / 1000;
  }
  function markOn(surfaces, l) {
    var cands = [l.ink, l.bg, '#FFFFFF', '#000000'], best = cands[0], score = -1;
    for (var i = 0; i < cands.length; i++) {
      var worst = 1000;
      for (var j = 0; j < surfaces.length; j++) {
        var d = Math.abs(lum(cands[i]) - lum(surfaces[j]));
        if (d < worst) worst = d;
      }
      if (worst > score) { score = worst; best = cands[i]; }
    }
    return best;
  }

  function render(ctx, idx, c1, c2) {
    var l = L[idx] || L[0];
    var M = l.multi || [l.accent, l.day, l.night, l.panel];
    var W = 200, H = 228;

    function R(x, y, w, h, col) {
      if (w <= 0 || h <= 0) return;
      ctx.fillStyle = col;
      ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
    }
    function bandRun(b, m) {
      var total = 0, i;
      for (i = 0; i < b.length; i++) total += b[i][0];
      var off = ((m % total) + total) % total;
      for (i = 0; i < b.length; i++) {
        if (off < b[i][0]) return [b[i][1], b[i][0] - off];
        off -= b[i][0];
      }
      return [b[0][1], 1];
    }
    function swatch(x, y, w, h) {
      var s = l.sw, i, j, run, r;
      if (s.t === 'bands') {
        for (j = 0; j < h; j++) { r = bandRun(s.b, j); R(x, y + j, w, 1, r[0]); }
      } else if (s.t === 'vstripe') {
        for (i = 0; i < w; i++) { r = bandRun(s.b, i); R(x + i, y, 1, h, r[0]); }
      } else if (s.t === 'diag') {
        for (j = 0; j < h; j++) {
          i = 0;
          while (i < w) {
            r = bandRun(s.b, i + j);
            run = Math.min(r[1], w - i);
            R(x + i, y + j, run, 1, r[0]);
            i += run;
          }
        }
      } else if (s.t === 'check' || s.t === 'cubes') {
        var n = s.size || 8, gap = (s.t === 'cubes') ? 2 : 0;
        var nx = Math.max(2, Math.round(w / n)), ny = Math.max(2, Math.round(h / n));
        if (gap) R(x, y, w, h, s.gut || l.bg);
        for (var gy = 0; gy < ny; gy++) {
          for (var gx = 0; gx < nx; gx++) {
            var x0 = Math.round(gx * w / nx), x1 = Math.round((gx + 1) * w / nx);
            var y0 = Math.round(gy * h / ny), y1 = Math.round((gy + 1) * h / ny);
            var ci = (s.t === 'check') ? (gx + gy) % s.c.length
                                       : (gx * 3 + gy * 7 + ((gx * gy) % 5)) % s.c.length;
            R(x + x0, y + y0, x1 - x0 - gap, y1 - y0 - gap, s.c[ci]);
          }
        }
      } else if (s.t === 'dither') {
        for (j = 0; j < h; j++) {
          var t = (h > 1) ? (j * 256) / (h - 1) : 0;
          for (i = 0; i < w; i++) {
            var th = BAYER[j % 4][i % 4] * 16 + 8;
            R(x + i, y + j, 1, 1, t > th ? s.c[1] : s.c[0]);
          }
        }
      } else if (s.t === 'blocks') {
        R(x, y, w, h, s.gut);
        for (i = 0; i < s.r.length; i++) {
          var q = s.r[i];
          R(x + q[0] * w / 100, y + q[1] * h / 100,
            (q[2] - q[0]) * w / 100, (q[3] - q[1]) * h / 100, s.c[q[4]]);
        }
      }
    }
    /* --- type ------------------------------------------------------------ */
    var capCache = {};
    function capSize(target, fam) {
      var k = target + fam;
      if (capCache[k]) return capCache[k];
      ctx.font = '100px ' + fam;
      var m = ctx.measureText('0');
      var asc = m.actualBoundingBoxAscent || 72;
      capCache[k] = Math.round(target * 100 / asc);
      return capCache[k];
    }
    var HEAVY = 'Impact, "Arial Narrow", "Roboto Condensed", sans-serif';

    /* cap-height ladder, mirroring silk_fit() in main.c: 16 -> 12 -> 8, with the
       cap BOTTOM held still so the baseline never moves between rungs */
    var RUNGS = [[16, 10], [12, 7], [8, 5]];
    function silk(s, x, capTop, maxW, align, col, forceRung) {
      var r = 0;
      if (forceRung !== undefined) r = forceRung;
      else {
        for (r = 0; r < RUNGS.length - 1; r++) {
          ctx.font = RUNGS[r][0] + 'px CadenceSilk, monospace';
          if (ctx.measureText(s).width <= maxW) break;
        }
      }
      ctx.font = RUNGS[r][0] + 'px CadenceSilk, monospace';
      ctx.fillStyle = col;
      ctx.textAlign = align || 'left';
      ctx.textBaseline = 'alphabetic';
      ctx.fillText(s, x, capTop + 10);
      ctx.textAlign = 'left';
    }
    function silk8(s, x, capTop, align, col) {
      ctx.font = '8px CadenceSilk, monospace';
      ctx.fillStyle = col;
      ctx.textAlign = align || 'left';
      ctx.fillText(s, x, capTop + 5);
      ctx.textAlign = 'left';
    }
    function heavy(s, x, capTop, cap, col, align) {
      ctx.font = capSize(cap, HEAVY) + 'px ' + HEAVY;
      ctx.fillStyle = col;
      ctx.textAlign = align || 'left';
      ctx.textBaseline = 'alphabetic';
      ctx.fillText(s, x, capTop + cap);
      ctx.textAlign = 'left';
    }
    function heavyW(s, cap) {
      ctx.font = capSize(cap, HEAVY) + 'px ' + HEAVY;
      return ctx.measureText(s).width;
    }
    /* HH : MM with the hand-built square colon, as on the watch */
    function timeBlock(cx, capTop, cap, hh, mm, col, colonCol) {
      var wh = heavyW(hh, cap), wm = heavyW(mm, cap);
      var dot = Math.max(3, Math.round(cap * 0.15));
      var gap = Math.round(cap * 0.20);
      var total = wh + gap + dot + gap + wm;
      var x = Math.round(cx - total / 2);
      heavy(hh, x, capTop, cap, col);
      R(x + wh + gap, capTop + cap * 0.28, dot, dot, colonCol);
      R(x + wh + gap, capTop + cap * 0.70, dot, dot, colonCol);
      heavy(mm, x + wh + gap + dot + gap, capTop, cap, col);
    }

    /* --- pixel primitives ------------------------------------------------- */
    function disc(cx, cy, r, col) {
      for (var y = -r; y < r; y++) {
        var hw = Math.round(Math.sqrt(Math.max(0, r * r - (y + 0.5) * (y + 0.5))));
        if (hw > 0) R(cx - hw, cy + y, hw * 2, 1, col);
      }
    }
    function moonDisc(cx, cy, r, pct, waxing, lit, dark) {
      disc(cx, cy, r, dark);
      var k = Math.cos(Math.PI * pct / 100 + (waxing ? 0 : 0));
      k = 1 - 2 * (pct / 100);                       /* cos(2*pi*phase) */
      for (var y = -r; y < r; y++) {
        var hw = Math.round(Math.sqrt(Math.max(0, r * r - (y + 0.5) * (y + 0.5))));
        if (hw <= 0) continue;
        var t = Math.round(k * hw), a, b;
        if (waxing) { a = t; b = hw; } else { a = -hw; b = -t; }
        if (b > a) R(cx + a, cy + y, b - a, 1, lit);
      }
    }
    function tri(cx, y, w, h, dir, col) {
      for (var i = 0; i < h; i++) {
        var num = (dir > 0) ? i : (h - i - 1);
        var ww = Math.max(1, w - Math.round(w * num / h));
        R(cx - Math.floor(ww / 2), y + i, ww, 1, col);
      }
    }
    function skyIcon(x, y, ink, dim, cond) {
      if (cond === 0 || cond === 1) {
        disc(x + 9, y + 9, 7, ink);
        R(x + 8, y - 1, 3, 3, ink); R(x + 8, y + 17, 3, 3, ink);
        R(x - 1, y + 8, 3, 3, ink); R(x + 17, y + 8, 3, 3, ink);
        R(x + 2, y + 2, 3, 3, ink); R(x + 14, y + 2, 3, 3, ink);
        R(x + 2, y + 14, 3, 3, ink); R(x + 14, y + 14, 3, 3, ink);
      }
      if (cond >= 1) {
        var ox = (cond === 1) ? x + 8 : x + 1, oy = (cond === 1) ? y + 8 : y + 4;
        R(ox + 2, oy + 6, 18, 7, dim);
        R(ox + 5, oy + 2, 9, 5, dim);
        R(ox + 12, oy + 4, 7, 4, dim);
      }
    }
    function frameR(x, y, w, h, t, col) {
      R(x, y, w, t, col); R(x, y + h - t, w, t, col);
      R(x, y + t, t, h - 2 * t, col); R(x + w - t, y + t, t, h - 2 * t, col);
    }

    var gut = (lum(l.bg) > 128) ? l.line : l.ink;
    R(0, 0, W, H, gut);

    /* A: time */
    R(0, 0, 136, 110, l.bg);
    var now = new Date();
    var NOW = now.getHours() * 60 + now.getMinutes();
    timeBlock(68, 37, 39, pad2(now.getHours()), pad2(now.getMinutes()), l.ink, M[0]);

    /* B: fabric */
    swatch(139, 0, 61, 110);

    /* D: complications - a faithful port of draw_comp() in main.c */
    function blend(a, b, wa) {
      function ch(h, i) { return parseInt(h.substr(1 + i * 2, 2), 16); }
      function snap(v) { return Math.min(255, Math.max(0, Math.round(v / 85) * 85)); }
      function hx(v) { var s = v.toString(16); return s.length < 2 ? '0' + s : s; }
      return '#' + hx(snap((ch(a, 0) * wa + ch(b, 0) * (100 - wa)) / 100)) +
                   hx(snap((ch(a, 1) * wa + ch(b, 1) * (100 - wa)) / 100)) +
                   hx(snap((ch(a, 2) * wa + ch(b, 2) * (100 - wa)) / 100));
    }
    function panel(bx, by, bw, bh, id) {
      if (!id) return;
      R(bx, by, bw, bh, l.panel);
      if (l.panel === l.bg) frameR(bx, by, bw, bh, 1, l.line);

      var ink = l.pink;
      var dim = (l.panel === l.bg) ? l.dim : blend(ink, l.panel, 65);
      if (Math.abs(lum(dim) - lum(l.panel)) < 90) dim = ink;
      var hot = l.accent;
      if (Math.abs(lum(hot) - lum(l.panel)) < 60) hot = ink;

      var wide = bw >= 140;
      var p = 6;
      var labY = by + p;
      var vcap = wide ? 25 : 20;
      var valY = by + bh - p - vcap;

      if (id === 1) {                                   /* second time zone */
        var zi = clayConfig.getItemByMessageKey('TZ_ZONE');
        var li = clayConfig.getItemByMessageKey('TZ_LABEL');
        var zone = (zi && zi.get()) || 'Europe/Paris';
        var lab = (li && li.get() && String(li.get()).trim())
                    ? String(li.get()).trim().toUpperCase().substring(0, 7)
                    : zone.split('/').pop().replace(/_/g, ' ').toUpperCase().substring(0, 7);
        var zt = new Date(), zh, zm;
        try {
          var parts = new Intl.DateTimeFormat('en-US', { timeZone: zone, hour12: false,
            hour: '2-digit', minute: '2-digit' }).formatToParts(zt);
          var o = {};
          parts.forEach(function (x) { o[x.type] = x.value; });
          zh = (+o.hour) % 24; zm = +o.minute;
        } catch (e) { zh = zt.getHours(); zm = zt.getMinutes(); }
        silk(lab, bx + p, labY, bw - p * 2 - 12, 'left', dim);
        var lit = (zh * 60 + zm) >= SUNRISE && (zh * 60 + zm) < SUNSET;
        if (lit) R(bx + bw - p - 7, labY + 2, 7, 7, ink);
        else frameR(bx + bw - p - 7, labY + 2, 7, 7, 2, ink);
        timeBlock(bx + bw / 2, valY, vcap, pad2(zh), pad2(zm), ink, ink);

      } else if (id === 2) {                            /* moon phase */
        var r = wide ? 17 : 12;
        moonDisc(bx + p + r, by + bh / 2, r, 62, true, ink, blend(ink, l.panel, 45));
        var tx = bx + p + r * 2 + 6;
        silk('WAX GIB', tx, labY, bw - (tx - bx) - p, 'left', dim);
        heavy('62', tx, valY, vcap, ink);
        silk('%', tx + heavyW('62', vcap) + 3, valY + vcap - 10, 16, 'left', dim, 0);

      } else if (id === 3) {                            /* sunrise / sunset */
        if (wide) {
          var half = bw / 2;
          tri(bx + p + 5, labY, 9, 8, -1, dim);
          silk('RISE', bx + p + 14, labY, half - p - 18, 'left', dim);
          timeBlock(bx + half / 2 + p / 2, valY, vcap - 2, '06', '26', ink, ink);
          tri(bx + half + p + 5, labY, 9, 8, 1, hot);
          silk('SET', bx + half + p + 14, labY, half - p - 18, 'left', dim);
          timeBlock(bx + half + half / 2 - p / 2, valY, vcap - 2, '20', '02', ink, ink);
          R(bx + half - 1, by + 5, 1, bh - 10, dim);
        } else {
          tri(bx + p + 5, labY, 9, 8, 1, hot);
          silk('SUNSET', bx + p + 14, labY, bw - p * 2 - 16, 'left', dim);
          timeBlock(bx + bw / 2, valY - 5 - 4, vcap, '20', '02', ink, ink);
          silk8('IN 2H 28M', bx + p, by + bh - p - 5, 'left', dim);
        }

      } else if (id === 4) {                            /* weather */
        skyIcon(bx + p, by + p + 2, ink, dim, 0);
        var wx = bx + p + (wide ? 30 : 26);
        heavy('71°', wx, valY, vcap, ink);
        if (wide) {
          silk('HI 94', bx + bw - p, by + bh / 2 - 12, 46, 'right', dim);
          silk('LO 71', bx + bw - p, by + bh / 2 + 3, 46, 'right', dim);
        } else {
          silk8('94/71', bx + bw - p, labY + 2, 'right', dim);
        }

      } else if (id === 5) {                            /* date: race plate */
        var px = bx + p, py = by + p, pw = bw - p * 2, ph = bh - p * 2;
        frameR(px, py, pw, ph, 2, ink);
        R(px + pw / 2 - 9, py, 7, 2, l.panel);          /* zip-tie punches */
        R(px + pw / 2 + 2, py, 7, 2, l.panel);
        var headBase = py + (wide ? 13 : 12);
        var plateY = by + bh - p - 6;
        var numH = Math.max(10, Math.min(vcap + 2, plateY - headBase - 5));
        var d = new Date();
        silk(DOW[d.getDay()], px + 6, headBase, pw / 2 - 6, 'left', ink);
        silk(MON[d.getMonth()], px + pw - 6, headBase, pw / 2 - 6, 'right', ink);
        heavy(String(d.getDate()), px + pw / 2, plateY - numH, numH, ink, 'center');
      }
    }
    if (c2) { panel(0, 113, 98, 63, c1); panel(101, 113, 99, 63, c2); }
    else { panel(0, 113, 200, 63, c1); }

    /* E: 24 cells */
    R(0, 179, W, H - 179, l.bg);
    var nowH = Math.floor(NOW / 60);
    for (var i = 0; i < 24; i++) {
      var cx = 4 + i * 8, mid = i * 60 + 30;
      var col = (mid >= SUNRISE && mid < SUNSET) ? l.day : l.night;
      if (mid >= SUNSET - 60 && mid < SUNSET) col = l.accent;
      R(cx, 188, 7, 16, col);
      if (i === nowH) {
        R(cx - 1, 185, 9, 22, l.ink);
        R(cx, 188, 7, 16, col);
        R(cx + 2, 194, 3, 4, l.ink);
      }
    }
    R(4, 183, 192, 2, l.dim);
    var mk = markOn([l.day, l.night, l.bg], l);
    R(4 + SUNRISE * 192 / 1440, 181, 2, 6, mk);
    R(4 + SUNSET * 192 / 1440, 181, 2, 6, mk);

    /* F: livery band */
    R(0, 210, W, 18, M[2]);
    R(0, 210, W, 2, gut);
    for (var k = 0; k < 3; k++) {
      for (var m = 0; m < 2; m++) {
        R(k * 8, 210 + m * 9, 8, 9, ((k + m) % 2) ? l.bg : l.chk);
      }
    }
    silk8(l.n, 196, 215, 'right', (lum(M[2]) > 150) ? '#000000' : '#FFFFFF');
  }

  clayConfig.on(clayConfig.EVENTS.AFTER_BUILD, function () {
    var livery = clayConfig.getItemByMessageKey('LIVERY');
    if (!livery || !livery.$element || !livery.$element[0]) return;

    var host = livery.$element[0];
    var wrap = document.createElement('div');
    wrap.style.cssText = 'padding:12px 0 4px;text-align:center;';

    var cv = document.createElement('canvas');
    cv.width = 200; cv.height = 228;
    cv.style.cssText = 'width:200px;height:228px;image-rendering:pixelated;' +
                       'image-rendering:crisp-edges;border-radius:4px;' +
                       'box-shadow:0 2px 10px rgba(0,0,0,.45);';
    wrap.appendChild(cv);

    var cap = document.createElement('div');
    cap.style.cssText = 'font-size:11px;letter-spacing:.08em;text-transform:uppercase;' +
                        'opacity:.55;margin-top:8px;';
    cap.textContent = 'Actual size · 200 × 228';
    wrap.appendChild(cap);

    host.parentNode.insertBefore(wrap, host);

    var ctx = cv.getContext('2d');
    function paint() {
      var c1 = clayConfig.getItemByMessageKey('COMP1');
      var c2 = clayConfig.getItemByMessageKey('COMP2');
      render(ctx,
             parseInt(livery.get(), 10) || 0,
             c1 ? parseInt(c1.get(), 10) : 3,
             c2 ? parseInt(c2.get(), 10) : 4);
    }

    livery.on('change', paint);
    ['COMP1', 'COMP2', 'TZ_ZONE', 'TZ_LABEL'].forEach(function (k) {
      var it = clayConfig.getItemByMessageKey(k);
      if (it) it.on('change', paint);
    });

    /* draw once immediately, then again once the pixel face has loaded */
    paint();
    try {
      var ff = new FontFace('CadenceSilk', 'url(' + SILK_SRC + ')');
      ff.load().then(function (loaded) {
        document.fonts.add(loaded);
        paint();
      })['catch'](function () { /* monospace fallback already drawn */ });
    } catch (e) { /* no FontFace API: the fallback stands */ }
  });
};
